const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Point(153.20, -29.69); // Grafton, New South Wales
    const startDate = '2020-01-14';
    const endDate = '2020-01-22';
    const rainfallThresholdInches = 6;
    const rainfallThresholdMM = rainfallThresholdInches * 25.4; // Convert inches to mm

    // 2. Data Acquisition & Check
    let chirpsCollection = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(startDate, endDate)
      .filterBounds(geometry);

    const collectionSize = await chirpsCollection.size().getInfo();
    console.log(`CHIRPS images found: ${collectionSize}`);

    if (collectionSize === 0) {
      console.log("No CHIRPS images found for the specified date range and location.");
      console.log("C1");
      return;
    }

    // Calculate total precipitation for the period
    const totalPrecipitationImage = chirpsCollection.sum();

    // 3. Processing & 4. Calculation
    // Use a scale appropriate for CHIRPS (0.05 degrees ~= 5500 meters)
    const scale = 5500; 

    const rainfallStats = await totalPrecipitationImage.reduceRegion({
      reducer: ee.Reducer.mean(), // For a point, mean is equivalent to getting the value
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9
    }).getInfo();

    const totalRainfallMM = rainfallStats ? rainfallStats.precipitation : null;

    // 5. Validation & Final Answer
    if (totalRainfallMM === null || isNaN(totalRainfallMM)) {
      console.log("Calculation failed: Unable to retrieve total rainfall.");
      console.log("C3");
      return;
    }

    const totalRainfallInches = totalRainfallMM / 25.4;

    console.log(`Total rainfall (mm): ${totalRainfallMM.toFixed(2)}`);
    console.log(`Total rainfall (inches): ${totalRainfallInches.toFixed(2)}`);
    console.log(`Threshold (inches): ${rainfallThresholdInches.toFixed(2)}`);

    if (totalRainfallInches > rainfallThresholdInches) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("An error occurred during the analysis:", error);
    // Attempt to identify specific GEE errors if possible
    if (error.message.includes("ImageCollection.filterDate")) {
        console.log("D"); // Likely a syntax or method error related to filtering
    } else if (error.message.includes("Image.reduceRegion")) {
        console.log("D"); // Likely a syntax or method error related to reduction
    } else if (error.message.includes("memory limit")) {
        console.log("D"); // Memory issue
    } else {
        console.log("D"); // Generic error catch
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
